#!/bin/bash
# DEPLOY_v2_fix3 — دقة كاشف التعارض + تتبّع مواضع أهداف الضوابط
# لا تفعيل إنتاج، ولا مساس بـapp.py.  الاستعمال:  bash DEPLOY_v2_fix3.sh
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2fix3.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2fix3.b64 > /tmp/v2fix3.tgz || { echo "B64_FAIL"; exit 1; }
[ -f mcp/server.py ] && cp mcp/server.py "mcp/server.py.bak_$(date +%s)"
tar xzf /tmp/v2fix3.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/retrieval_layer_validate.py > /tmp/v2val3.log 2>&1 &
disown
echo "بدأت. تابع:  tail -f /tmp/v2val3.log"
